    public int[] applyOperations(int[] nums) {
        int[] answer = new int[nums.length];
        int write = 0;
        int index = 0;
        while (index < nums.length) {
            if (index + 1 < nums.length && nums[index] == nums[index + 1]) {
                if (nums[index] != 0) {
                    answer[write++] = nums[index] * 2;
                }
                index += 2;
            } else {
                if (nums[index] != 0) {
                    answer[write++] = nums[index];
                }
                index++;
            }
        }
        return answer;
    }
}

